async (__variable) => {
const {Legend, Swatches} = await (import("https://api.observablehq.com/@d3/color-legend.js?v=4").then((_) => {
  const module = __variable._module._runtime.module(_.default);
  const outputs = new Map(Array.from(__variable._outputs, (v) => [v._name, v]));
  outputs.get("Legend")?.import("Legend", module);
  outputs.get("Swatches")?.import("Swatches", module);
  return {};
}));

return {Legend,Swatches};
}

